input.command:
$v=$env:WIKI_MASTER_VAULT
foreach($f in 'wiki/concepts/Beacon Protocol.md','wiki/concepts/Beacon Protocol Draft.md','wiki/authored/beacon/overview.md','wiki/authored/beacon/architecture.md','wiki/authored/beacon/backlog/parallel-workers.md','raw/clippings/Beacon Study.md','moc/Signals.md'){ "=== $f"; Get-Content -LiteralPath "$v/$f" -TotalCount 40 }
"=== others"; Get-ChildItem $v/wiki,$v/moc,$v/raw -Recurse -File | % { $_.FullName.Substring($v.Length+1) }
"=== grep"; Select-String -Path "$v/wiki/*/*.md","$v/wiki/*/*/*.md","$v/moc/*.md" -Pattern 'Beacon' -List | % { $_.Path.Substring($v.Length+1) }

